    id: 'shabbat-hayom', category: 'chabbat', title: 'Chabbat Hayom LaChem', hebrew: 'שַׁבָּת הַיּוֹם לַיְיָ',
    author: 'Signé « Chemouel » (médiéval)', audio: yt('shabbat hayom lashem zemer'),
